    if (!clientAuth) return;
    try {
      if (isAgentRole(clientAuth.role)) {
        json(res, 403, httpError("forbidden", "Only supervisor or admin can export CRM recipients."));
        return;
      }
      const client = await getScopedClientById(prisma, clientAuth.clientId);
      if (!client) {
        json(res, 404, httpError("client_not_found", "Client not found"));
        return;
      }
      if (client.status !== "ACTIVE") {
        json(res, 403, httpError("client_inactive", "Client inactive"));
        return;
      }
      if (
        !(await enforceAppCapability(prisma, res, {
          client,
          userId: clientAuth.userId,
          capability: "crm",
          endpoint: "/app/crm/campaign-recipients",
          requestId,
        }))
      ) {
        return;
      }
      const tenants = await getTenants();
      const tenant = tenants[client.clientKey];
      if (!tenant) {
        json(res, 404, httpError("tenant_not_found", "Tenant not found"));
        return;
      }
      const configuredStatuses = (
        await resolveCrmBusinessStatuses({
          prisma,
          clientId: client.id,
          tenant,
        })
      ).statuses;
      const allowedStatuses = new Set(
        configuredStatuses
          .filter((item) => item.isActive && item.campaignEligible)
          .map((item) => item.id)
      );
      const requestedStatuses = String(query.statuses ?? "")
        .split(",")
        .map((item) => item.trim().toUpperCase())
        .filter((item) => allowedStatuses.has(item));
      if (requestedStatuses.length === 0) {
        json(res, 400, httpError("bad_request", "Select at least one campaign eligible status."));
        return;
      }
      const limit = Math.min(
        5000,
        Math.max(1, Number.isFinite(Number(query.limit)) ? Math.floor(Number(query.limit)) : 1000)
      );
      const leads = await prisma.lead.findMany({
        where: {
          tenantId: client.id,
          status: { in: requestedStatuses },
        },
        orderBy: [{ updatedAt: "desc" }, { createdAt: "desc" }],
        take: limit,
        select: {
          id: true,
          name: true,
          phone: true,
          waId: true,
          waIdCanonical: true,
          externalUserHash: true,
          externalUserRef: true,
          legacyWaId: true,
          contactChannelIdentity: {
            select: {
              contact: {
                select: {
                  lifecycle: true,
                },
              },
            },
          },
          status: true,
          updatedAt: true,
        },
      });
      const lifecycleLookupKeys = Array.from(
        new Set(
          leads
            .flatMap((lead) => [
              lead.waId,
              lead.waIdCanonical,
              lead.externalUserRef,
              lead.legacyWaId,
              String(lead.phone ?? "").replace(/\D/g, ""),
            ])
            .map((value) => String(value ?? "").trim())
            .filter(Boolean)
        )
      );
      const [operationallyExcludedWaIds] = await Promise.all([
        loadOperationallyExcludedWaIds(prisma, {
          clientId: client.id,
          waIds: lifecycleLookupKeys,
        }),
      ]);
      const contactsByLookupKey = new Map<string, { lifecycle: unknown }>();
      if (lifecycleLookupKeys.length > 0) {
        const contacts = await prisma.contact.findMany({
          where: {
            clientId: client.id,
            OR: [
              { waId: { in: lifecycleLookupKeys } },
              { externalUserRef: { in: lifecycleLookupKeys } },
              { legacyWaId: { in: lifecycleLookupKeys } },
            ],
          },
          select: { waId: true, externalUserRef: true, legacyWaId: true, lifecycle: true },
        });
        for (const contact of contacts) {
          for (const key of [contact.waId, contact.externalUserRef, contact.legacyWaId]) {
            const normalizedKey = String(key ?? "").trim();
            if (normalizedKey) contactsByLookupKey.set(normalizedKey, { lifecycle: contact.lifecycle });
          }
        }
      }
      const seen = new Set<string>();
      const items = leads
        .map((lead) => {
          const matchedContact =
            lead.contactChannelIdentity?.contact ??
            contactsByLookupKey.get(lead.waIdCanonical ?? "") ??
            contactsByLookupKey.get(lead.waId) ??
            contactsByLookupKey.get(lead.externalUserRef ?? "") ??
            contactsByLookupKey.get(lead.legacyWaId ?? "") ??
            contactsByLookupKey.get(String(lead.phone ?? "").replace(/\D/g, "")) ??
            null;
          if (matchedContact && !isOperationalContactLifecycle(matchedContact.lifecycle)) return null;
          if (
            [
              lead.waId,
              lead.waIdCanonical,
              lead.externalUserRef,
              lead.legacyWaId,
              String(lead.phone ?? "").replace(/\D/g, ""),
            ].some((candidate) => operationallyExcludedWaIds.has(String(candidate ?? "").trim()))
          ) {
            return null;
          }
          if (
            [
              lead.waId,
              lead.waIdCanonical,
              lead.externalUserHash,
              lead.name,
              lead.phone,
            ].some(isAnonymizedCampaignMarker)
          ) {
            return null;
          }
          const phone = String(lead.phone ?? lead.waIdCanonical ?? lead.waId ?? "").replace(/\D/g, "");
          if (!phone || seen.has(phone)) return null;
          seen.add(phone);
          return {
            leadId: lead.id,
            name: lead.name,
            phone,
            status: lead.status,
            updatedAt: lead.updatedAt.toISOString(),
          };
        })
        .filter(Boolean);
      logger.info({
        event: "app.crm.campaign_recipients.prepared",
        requestId,
        clientId: client.id,
        clientKey: client.clientKey,
        userId: clientAuth.userId,
        statuses: requestedStatuses,
        count: items.length,
      });
      json(res, 200, {
        ok: true,
        statuses: requestedStatuses,
        count: items.length,
        items,
        numbers: items.map((item) => item?.phone).filter(Boolean),
      });
    } catch (error) {
      logger.error({
        event: "app.crm.campaign_recipients.error",
        message: (error as Error).message,
        requestId,
      });
      json(res, 500, httpError("server_error", "Server error"));
    }
    return;
