async function requireMfaAppAccess(
  req: IncomingMessage,
  res: ServerResponse,
  requestId: string,
  endpoint: string
) {
  const prisma = getPrisma();
  const clientAuth = requireClientAuth(req, res);
  if (!clientAuth) return null;
  if (isAgentRole(clientAuth.role)) {
    if (endpoint === "/app/mfa/verify-shadow") {
      logger.info({
        event: "mfa.shadow.verify_denied",
        reason: "forbidden",
        clientId: clientAuth.clientId,
        userId: clientAuth.userId,
        requestId,
      });
    }
    json(res, 403, httpError("forbidden", "Only supervisor or admin can manage MFA settings."));
    return null;
  }
  const client = await getScopedClientById(prisma, clientAuth.clientId);
  if (!client) {
    json(res, 404, httpError("client_not_found", "Client not found"));
    return null;
  }
  if (client.status !== "ACTIVE") {
    json(res, 403, httpError("client_inactive", "Client inactive"));
    return null;
  }
  const enabled = await enforceAppFeature(prisma, res, {
    client,
    userId: clientAuth.userId,
    feature: "mfa",
    endpoint,
    requestId,
  });
  if (!enabled) {
    if (endpoint === "/app/mfa/verify-shadow") {
      logger.info({
        event: "mfa.shadow.verify_denied",
        reason: "feature_disabled",
        clientId: client.id,
        userId: clientAuth.userId,
        requestId,
      });
    }
    return null;
  }
  return { clientAuth, client };
}

